 {tab==='Digest'&&<><Toolbar title="Weekly product digest" sub="A concise summary of current progress, delivery risks and recent signals." action={<div className="top-actions"><button className="secondary" onClick={async()=>{const summary={feedback:feedback.length,feedbackOpen:feedback.filter(x=>x.status==='OPEN').length,requirements:requirements.length,requirementsInBuild:requirements.filter(x=>x.status==='IN_BUILD').length,requirementsShipped:requirements.filter(x=>x.status==='SHIPPED').length,actions:actions.length,actionsOutstanding:actions.filter(x=>x.status!=='DONE').length,actionsBlocked:actions.filter(x=>x.status==='BLOCKED').length,releases:releases.length,releasesReady:releases.filter(x=>x.status==='READY').length,releasesShipped:releases.filter(x=>x.status==='RELEASED').length,metrics:metrics.map(m=>({name:m.name,actual:m.actual,target:m.target,progressPercent:m.progressPercent}))};const saved=await run(()=>api<any>(`/products/${productId}/digest-snapshots`,json('POST',{title:`Weekly digest — ${new Date().toLocaleDateString()}`,summary}),orgId,token));if(saved){setDigestSnapshots(v=>[saved,...v]);setNotice('Digest snapshot saved.');}}}>Save snapshot</button><button className="secondary" onClick={()=>{const text=[`Product OS weekly digest — ${currentProduct?.name}`,`Feedback: ${feedback.length} total; ${feedback.filter(x=>x.status==='OPEN').length} open; ${feedback.filter(x=>x.status==='DONE').length} resolved.`,`Requirements: ${requirements.length} total; ${requirements.filter(x=>x.status==='IN_BUILD').length} in build; ${requirements.filter(x=>x.status==='SHIPPED').length} shipped.`,`Action items: ${actions.length} total; ${actions.filter(x=>x.status!=='DONE').length} outstanding; ${actions.filter(x=>x.status==='BLOCKED').length} blocked.`,`Releases: ${releases.length} total; ${releases.filter(x=>x.status==='READY').length} ready; ${releases.filter(x=>x.status==='RELEASED').length} released.`,`KPIs: ${metrics.length} tracked.`].join('\n');const blob=new Blob([text],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='product-os-weekly-digest.txt';a.click();URL.revokeObjectURL(url);}}>↓ Export digest</button></div>}/><div className="stats-grid"><Stat label="Feedback open" value={feedback.filter(x=>x.status==='OPEN').length} note="Needs triage" icon="◉"/><Stat label="Requirements in build" value={requirements.filter(x=>x.status==='IN_BUILD').length} note="Active delivery" icon="▤"/><Stat label="Blocked actions" value={actions.filter(x=>x.status==='BLOCKED').length} note="Requires attention" icon="!"/><Stat label="Upcoming releases" value={releases.filter(x=>x.status!=='RELEASED').length} note="Not yet released" icon="↗"/></div><div className="content-grid"><section className="panel"><PanelHead title="Key risks and attention points" sub="Items that may need a product or delivery decision."/><div className="compact-list">{actions.filter(a=>a.status==='BLOCKED'||a.priority==='URGENT'||(a.dueAt&&new Date(a.dueAt)<new Date()&&a.status!=='DONE')).slice(0,8).map(a=><div className="compact-item" key={a.id}><span className="priority-dot urgent"/><div><b>{a.title}</b><small>{titleCase(a.status)} · {titleCase(a.priority)} · Due {date(a.dueAt)}</small></div></div>)}{!actions.some(a=>a.status==='BLOCKED'||a.priority==='URGENT'||(a.dueAt&&new Date(a.dueAt)<new Date()&&a.status!=='DONE'))&&<EmptyLine text="No blocked, urgent or overdue action items detected."/>}</div></section><section className="panel"><PanelHead title="Latest feedback signals" sub="Recent feedback to review."/><div className="compact-list">{[...feedback].slice(0,6).map(f=><div className="compact-item" key={f.id}><span className="priority-dot"/><div><b>{f.text}</b><small>{f.source} · {titleCase(f.sentiment)} · {titleCase(f.severity)}</small></div></div>)}{!feedback.length&&<EmptyLine text="No feedback has been captured yet."/>}</div></section></div><section className="panel"><PanelHead title="Digest narrative" sub="A snapshot you can use in a weekly product review."/><p className="digest-copy">{currentProduct?.name||'This product'} currently has {feedback.length} feedback records, {requirements.length} requirements, {actions.length} action items and {releases.length} releases. {actions.filter(a=>a.status==='BLOCKED').length} action items are blocked, while {actions.filter(a=>a.status!=='DONE').length} remain outstanding. {requirements.filter(r=>r.status==='SHIPPED').length} requirements have shipped. There are {metrics.length} performance indicators available for outcome tracking.</p><p className="muted small-text">This digest is generated from the current product records. Saved snapshots below enable historical comparison.</p></section><section className="panel"><PanelHead title="Week-over-week movement" sub="Compare the latest saved checkpoint with the previous one."/>{digestSnapshots.length>=2?<div className="table-panel"><table><thead><tr><th>Measure</th><th>Previous</th><th>Latest</th><th>Change</th></tr></thead><tbody>{(['feedback','feedbackOpen','requirements','requirementsInBuild','requirementsShipped','actions','actionsOutstanding','actionsBlocked','releases','releasesReady','releasesShipped'] as const).map(key=>{const latest=digestSnapshots[0]?.summary?.[key]??0;const previous=digestSnapshots[1]?.summary?.[key]??0;const diff=Number(latest)-Number(previous);return <tr key={key}><td>{titleCase(key)}</td><td>{previous}</td><td>{latest}</td><td><span className={`pill ${diff>0?'red':diff<0?'green':''}`}>{diff>0?'+':''}{diff}</span></td></tr>;})}</tbody></table></div>:<EmptyLine text="Save at least two weekly digest snapshots to see week-over-week movement."/>}</section><section className="panel"><PanelHead title="Saved digest snapshots" sub="Historical product-review checkpoints."/><div className="compact-list">{digestSnapshots.map(s=><div className="compact-item" key={s.id}><span className="priority-dot"/><div><b>{s.title}</b><small>{new Date(s.createdAt).toLocaleString()} · {s.summary?.feedback??0} feedback · {s.summary?.actions??0} actions · {s.summary?.releases??0} releases</small></div></div>)}{!digestSnapshots.length&&<EmptyLine text="No snapshots saved yet. Save this week’s digest to begin tracking trends."/>}</div></section></>}
 {tab==='Audit'&&<><Toolbar title="Audit history" sub="A record of changes made across this product workspace."/><div className="panel table-panel"><table><thead><tr><th>Activity</th><th>Entity</th><th>Actor</th><th>When</th></tr></thead><tbody>{audit.map(a=><tr key={a.id}><td className="primary-cell">{titleCase(a.action)}<small>{a.entityId}</small></td><td>{a.entityType}</td><td>{a.actor?.name||a.actor?.email||'System'}</td><td>{new Date(a.createdAt).toLocaleString()}</td></tr>)}{!audit.length&&<tr><td colSpan={4}><EmptyLine text="No audit events available."/></td></tr>}</tbody></table></div></>}
 {tab==='Notifications'&&<><Toolbar title="Notifications" sub="Workspace assignments and activity updates." action={<button className="secondary" onClick={async()=>{await api('/notifications/read-all',json('POST',{}),orgId,token);setNotifications(v=>v.map(n=>({...n,readAt:n.readAt||new Date().toISOString()})));}}>Mark all as read</button>}/><div className="panel compact-list">{notifications.map(n=><div className="compact-item" key={n.id}><span className={`priority-dot ${n.readAt?'':'urgent'}`}/><div><b>{n.title}</b><small>{n.body} · {new Date(n.createdAt).toLocaleString()}</small></div>{!n.readAt&&<button className="text-button" onClick={async()=>{await api(`/notifications/${n.id}/read`,json('PATCH',{}),orgId,token);setNotifications(v=>v.map(x=>x.id===n.id?{...x,readAt:new Date().toISOString()}:x));}}>Mark read</button>}</div>)}{!notifications.length&&<EmptyLine text="You're all caught up. No notifications yet."/>}</div></>}
 {tab==='Archived products'&&<><Toolbar title="Archived products" sub="Restore a product to make it active again. Its historical records remain intact." action={<button className="secondary" onClick={async()=>setArchivedProducts(await api<Product[]>('/products/archived',{},orgId,token))}>Refresh list</button>}/><div className="panel table-panel"><table><thead><tr><th>Product</th><th>Description</th><th>Archived on</th><th>Action</th></tr></thead><tbody>{archivedProducts.map((p:any)=><tr key={p.id}><td className="primary-cell">{p.name}<small>{p.id}</small></td><td>{p.description||'—'}</td><td>{date(p.archivedAt)}</td><td><button className="secondary" disabled={busy} onClick={async()=>{const restored=await run(()=>api(`/products/${p.id}/restore`,json('POST',{}),orgId,token));if(restored){const [active,archived]=await Promise.all([api<Product[]>('/products',{},orgId,token),api<Product[]>('/products/archived',{},orgId,token)]);setProducts(active);setArchivedProducts(archived);if(!productId)setProductId(p.id);setNotice(`${p.name} restored successfully.`);}}}>Restore product</button></td></tr>)}{!archivedProducts.length&&<tr><td colSpan={4}><EmptyLine text="No archived products. Products you archive will appear here."/></td></tr>}</tbody></table></div><section className="panel"><PanelHead title="Archive behaviour" sub="Archiving is reversible and does not delete product data."/><p className="digest-copy">Archived products are removed from the active product selector. Their feedback, requirements, action items, releases, metrics, comments and audit history are retained. Restoring a product returns it to the active selector.</p></section></>}
